CREATE DATABASE IF NOT EXISTS prossor_colegio CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE prossor_colegio;
CREATE TABLE IF NOT EXISTS institutions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NULL,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('student','parent','teacher','admin','superadmin') NOT NULL DEFAULT 'student',grade_level TINYINT UNSIGNED NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_login_at DATETIME NULL,FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE SET NULL, CHECK(grade_level IS NULL OR grade_level BETWEEN 5 AND 11)) ENGINE=InnoDB;
ALTER TABLE users MODIFY id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT;
CREATE TABLE IF NOT EXISTS parent_student_relationships(parent_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status ENUM('pending','active','rejected') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(parent_id,student_id),FOREIGN KEY(parent_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS subjects(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,icon VARCHAR(20) NOT NULL DEFAULT '✦') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS academic_competencies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,subject_id INT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,description TEXT NULL,UNIQUE(subject_id,name),FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS topics(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,competency_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,grade_level TINYINT UNSIGNED NOT NULL,FOREIGN KEY(competency_id) REFERENCES academic_competencies(id) ON DELETE CASCADE,UNIQUE(competency_id,name,grade_level),INDEX(grade_level)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS questions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,topic_id BIGINT UNSIGNED NOT NULL,grade_level TINYINT UNSIGNED NOT NULL,type ENUM('single_choice','true_false','short_answer','numeric') NOT NULL DEFAULT 'single_choice',prompt TEXT NOT NULL,answer_key VARCHAR(500) NOT NULL,explanation TEXT NOT NULL,difficulty TINYINT UNSIGNED NOT NULL DEFAULT 2,source VARCHAR(190) NOT NULL DEFAULT 'Contenido original de demostración',review_status ENUM('draft','approved') NOT NULL DEFAULT 'approved',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE CASCADE,UNIQUE(topic_id,prompt(180)),INDEX(grade_level,difficulty)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS question_options(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question_id BIGINT UNSIGNED NOT NULL,label CHAR(1) NOT NULL,body TEXT NOT NULL,FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE,UNIQUE(question_id,label)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS diagnostic_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,grade_level TINYINT UNSIGNED NOT NULL,total_questions INT UNSIGNED NOT NULL,correct_count INT UNSIGNED NOT NULL DEFAULT 0,started_at DATETIME NOT NULL,finished_at DATETIME NULL,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(student_id,finished_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS diagnostic_answers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,attempt_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,answer VARCHAR(1000) NOT NULL,is_correct BOOLEAN NOT NULL,answered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(attempt_id) REFERENCES diagnostic_attempts(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES questions(id),UNIQUE(attempt_id,question_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,answer VARCHAR(1000) NOT NULL,is_correct BOOLEAN NOT NULL,duration_seconds INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES questions(id),INDEX(student_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS student_competency_progress(student_id BIGINT UNSIGNED NOT NULL,competency_id BIGINT UNSIGNED NOT NULL,attempts INT UNSIGNED NOT NULL DEFAULT 0,correct_count INT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(student_id,competency_id),FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(competency_id) REFERENCES academic_competencies(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS learning_plans(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,objective TEXT NOT NULL,source ENUM('rules','ai') NOT NULL DEFAULT 'rules',status ENUM('active','completed','archived') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS learning_plan_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,plan_id BIGINT UNSIGNED NOT NULL,topic_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,minutes_estimate SMALLINT UNSIGNED NOT NULL DEFAULT 15,priority TINYINT UNSIGNED NOT NULL DEFAULT 2,is_completed BOOLEAN NOT NULL DEFAULT FALSE,completed_at DATETIME NULL,FOREIGN KEY(plan_id) REFERENCES learning_plans(id) ON DELETE CASCADE,FOREIGN KEY(topic_id) REFERENCES topics(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS teacher_groups(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,teacher_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,grade_level TINYINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(teacher_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS group_students(group_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(group_id,student_id),FOREIGN KEY(group_id) REFERENCES teacher_groups(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS exams(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS exam_questions(exam_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,position SMALLINT UNSIGNED NOT NULL,PRIMARY KEY(exam_id,question_id),FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES questions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS exam_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,exam_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,score DECIMAL(5,2) NULL,started_at DATETIME NOT NULL,finished_at DATETIME NULL,FOREIGN KEY(exam_id) REFERENCES exams(id),FOREIGN KEY(student_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS exam_answers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,attempt_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,answer TEXT NOT NULL,is_correct BOOLEAN NOT NULL,FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES questions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS chat_conversations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL DEFAULT 'Nueva conversación',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS chat_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT UNSIGNED NOT NULL,role ENUM('user','assistant') NOT NULL,content TEXT NOT NULL,provider VARCHAR(40) NOT NULL DEFAULT 'local-guided',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(conversation_id) REFERENCES chat_conversations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS academic_alerts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,rule_key VARCHAR(80) NOT NULL,message VARCHAR(255) NOT NULL,resolved_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wellbeing_checkins(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,mood TINYINT UNSIGNED NOT NULL,preparedness TINYINT UNSIGNED NOT NULL,needs_help BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS achievements(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(255) NOT NULL,points INT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS student_achievements(student_id BIGINT UNSIGNED NOT NULL,achievement_id INT UNSIGNED NOT NULL,earned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(student_id,achievement_id),FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(achievement_id) REFERENCES achievements(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS subscription_plans(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,price_cop INT UNSIGNED NOT NULL DEFAULT 0,features TEXT NOT NULL,is_available BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_subscriptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,plan_id INT UNSIGNED NOT NULL,status ENUM('pending','active','expired','cancelled') NOT NULL DEFAULT 'active',starts_at DATE NOT NULL,ends_at DATE NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(plan_id) REFERENCES subscription_plans(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,subscription_id BIGINT UNSIGNED NOT NULL,provider VARCHAR(60) NOT NULL,status VARCHAR(30) NOT NULL,amount_cop INT UNSIGNED NOT NULL,reference VARCHAR(190) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subscription_id) REFERENCES user_subscriptions(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,event VARCHAR(100) NOT NULL,details JSON NULL,ip_address VARCHAR(45) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS application_settings(setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_throttles(email_hash CHAR(64) NOT NULL,ip_hash CHAR(64) NOT NULL,failures TINYINT UNSIGNED NOT NULL DEFAULT 0,window_started_at DATETIME NOT NULL,blocked_until DATETIME NULL,PRIMARY KEY(email_hash,ip_hash),INDEX(blocked_until)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS access_codes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code_hash CHAR(64) NOT NULL UNIQUE,code_type ENUM('parent_student','teacher_group') NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,used_by BIGINT UNSIGNED NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(used_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(code_type,expires_at),INDEX(entity_id,code_type)) ENGINE=InnoDB;
